'use client';
import React, { ReactElement, useState, useEffect } from 'react';
import { useSearchParams } from 'next/navigation';
import { componentMap, menuAPI } from '@/routes';
import { useRoutes, RouteData } from '@/useRoutes';

export default function RouteContent(): ReactElement {
  const searchParams = useSearchParams();
  const contentSlug = searchParams.get('content') || 'home';
  
  const { routes: dbRoutes, loading: routesLoading } = useRoutes();
  const [Component, setComponent] = useState<React.ComponentType | null>(null);
  const [routeData, setRouteData] = useState<RouteData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadContent = async () => {
      // Ждем загрузки маршрутов с бэка
      if (routesLoading) return;

      if (contentSlug === 'home') {
        const homeModule = await import('./default_page/Default_page');
        setComponent(() => homeModule.default);
        setLoading(false);
        return;
      }

      try {
        // 1. Ищем динамические данные в массиве из БД
        const routeInfo = dbRoutes.find(r => r.id === contentSlug);
        if (!routeInfo) throw new Error(`Маршрут ${contentSlug} не найден в БД`);

        // 2. Сохраняем динамические данные
        setRouteData(routeInfo);

        // 3. Ищем статический компонент
        const loader = componentMap[contentSlug] || (() => import('./stub/stub'));
        const module = await loader();
        setComponent(() => module.default);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Ошибка загрузки');
      } finally {
        setLoading(false);
      }
    };

    loadContent();
  }, [contentSlug, routesLoading, dbRoutes]);

  if (loading || routesLoading) return <div>Загрузка...</div>;
  if (error) return <div>Ошибка: {error}</div>;
  if (!Component || !routeData) return <div>Данные не загружены</div>;

  // Передаем данные в компонент
  return React.createElement(Component, { routeData });
}